def all_prefixes(string: str) -> List[str]:
    """ Return list of all prefixes from shortest to longest of the input string
    >>> all_prefixes('abc')
    ['a', 'ab', 'abc']
    """

    prefixes = [string]
    for i in range(len(string)):
        prefixes.append(string[:i+1])
    return prefixes


def all_suffixes(string: str) -> List[str]:
    """ Return list of all suffixes from shortest to longest of the input string
    >>> all_suffixes('abc')
    ['abc', 'bc', 'c']
    """
    suffixes = [string]
    for i in range(len(string)):
        suffixes.append(string[i:])
    return suffixes


def all_substrings(string: str) -> List[str]:
    """ Return list of all substrings from shortest to longest of the input string
    >>> all_substrings('abc')
    ['a', 'ab', 'abc', 'b', 'bc', 'c']
    """
    substrings = []
    for i in range(len(string)):
        for j in range(i, len(string)):
            substrings.append(string[i:j+1])
    return substrings


def all_palindromes(string: str) -> List[str]:
    """ Return list of all palindromes from shortest to longest of the input string
    >>> all_palindromes('abc')
    ['a', 'ab', 'abc', 'aba', 'b', 'ba', 'c', 'ca', 'cba', 'cb', 'c']
    """
    palindromes = []
    for i in range(len(string)):
        for j in range(i, len(string)):
            if string[i:j+1] == string[i:j+1][::-1]:
                palindromes.append(string[i:j+1])
    return palindromes


def all_anagrams(string: str) -> List[str]:
    """ Return list of all anagrams of the input string
    >>> all_anagrams('abc')
