def is_prime(n: int) -> bool:
    """ For a given number n, determine if it is prime
    >>> is_prime(15)
    False
    >>> is_prime(17)
    True
    """
    if n < 2:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True


def is_perfect(n: int) -> bool:
    """ For a given number n, determine if it is perfect
    >>> is_perfect(15)
    False
    >>> is_perfect(28)
    True
    """
    if n < 1:
        return False
    total = 0
    for i in range(1, n):
        if n % i == 0:
            total += i
    return total == n


